  "panel.action.checking-busy-title": { en: "Checking the official source; please wait", zh: "\u6B63\u5728\u5411\u5B98\u65B9\u6E90\u67E5\u8BE2\u7248\u672C\u4FE1\u606F\uFF0C\u8BF7\u7A0D\u5019", draft: true },
